FPROJ=formula('Q=XWQ; K=XWK; V=XWV',{'X':'N×d matrix, one token row per position','WQ,WK':'learned d×dk query/key projections','WV':'learned d×dv value projection','Q,K':'N×dk projected query/key matrices','V':'N×dv projected value matrix','N':'number of input token positions','d':'model feature width','dk':'query/key width','dv':'value width'},{'X,WQ,WK,WV,Q,K,V':'dimensionless activations/weights','N,d,dk,dv':'dimensionless integer counts'},['Row-vector convention; one self-attention head; biases omitted as in the source.'])
FATT=formula('S=QKᵀ/√dk+M; P_ij=exp(S_ij)/Σ_r exp(S_ir); H=PV',{'Q,K':'query/key matrices, N×dk','V':'value matrix, N×dv','dk':'shared query/key width','M':'N×N additive causal mask: 0 for j≤i, −∞ for j>i','S':'N×N masked score table','P':'N×N attention weights, row-normalized over key index r','H':'N×dv head output','i':'query row','j,r':'key-position indices','N':'token count'},{'Q,K,V,S,M,H':'dimensionless numerical representations; −∞ is a mask sentinel','P':'dimensionless probabilities','dk,N,i,j,r':'dimensionless counts or indices'},['Inclusive causal mask; at least one finite allowed score in each row; scale once; softmax over keys before multiplying values.'])
FMHA=formula('Y=Concat(H¹,…,Hᴬ)WO',{'Hᶜ':'N×dv output matrix from head c','A':'number of heads','c':'head index, 1≤c≤A','WO':'learned (A dv)×d output projection','Y':'N×d multi-head output','N':'token count','dv':'per-head value/output width','d':'model feature width','Concat':'concatenation along features, retaining N token rows'},{'Hᶜ,WO,Y':'dimensionless activations/weights','A,c,N,dv,d':'dimensionless counts or index'},['Every head has its own projections; all heads use the same N rows and dv here; output projection is not merely a reshape.'])
FFN=formula('FFN(z)=ReLU(zW1+b1)W2+b2; ReLU(a)=max(0,a); n_param=2dm+m+d',{'z':'1×d token feature row','W1':'d×m first weight matrix','b1':'1×m first bias','W2':'m×d second weight matrix','b2':'1×d second bias','m':'hidden width','d':'input/output model width','a':'an element of the first affine output','n_param':'number of trainable scalar weights and biases in this FFN'},{'z,W1,b1,W2,b2,a,FFN(z)':'dimensionless activations/weights','m,d,n_param':'dimensionless integer counts'},['ReLU acts elementwise between affine maps; weights shared across positions; parameter-count formula is derived from the source’s two matrices and two biases.'])
FLN=formula('μ=(1/d)Σ_r x_r; v=(1/d)Σ_r(x_r−μ)²; LN(x)_r=γ_r(x_r−μ)/√(v+ε)+β_r',{'x':'one token feature vector of width d','r':'feature index from 1 to d','d':'number of normalized features','μ':'feature mean for this token','v':'population feature variance for this token','γ,β':'learned per-feature gain and offset, each width d','ε':'nonnegative denominator stabilizer; normally strictly positive in implementations','LN(x)':'normalized and affine-transformed token vector'},{'x,μ,γ,β,LN(x)':'dimensionless numerical features or affine parameters','v,ε':'squared feature scale, dimensionless in this representation','d,r':'dimensionless count or index'},['Normalize features separately for each token; the source prints ε=0 shorthand; ε=0 is usable only for nonzero variance; positive ε is an explicitly declared implementation qualification.'])
FPRE=formula('O=X+MHA(LN1(X)); H=O+FFN(LN2(O))',{'X':'N×d input token matrix','LN1,LN2':'separate per-token feature normalizations','MHA':'masked multi-head attention mapping N×d to N×d','O':'N×d intermediate residual stream','FFN':'positionwise two-affine-layer feedforward map','H':'N×d block output','N':'token count','d':'model width'},{'X,O,H':'dimensionless activations','N,d':'dimensionless counts','LN1,LN2,MHA,FFN':'functions on dimensionless feature arrays'},['The source’s pre-norm equations; no post-sum final normalization is inserted; mask conventions remain explicit; dropout omitted.'])
FEMB=formula('X_word=WE; X=X_word+P',{'W':'N×|Vocab| one-hot token-selection matrix','E':'|Vocab|×d token-embedding matrix','P':'N×d position vectors selected for the current positions','X_word':'N×d token lookup result','X':'N×d composite input','N':'sequence length','|Vocab|':'vocabulary size, not value matrix V','d':'embedding/model width'},{'W':'dimensionless 0/1 selectors','E,P,X_word,X':'dimensionless feature arrays','N,|Vocab|,d':'dimensionless integer counts'},['IDs must use a stated indexing convention; add positions elementwise; learned absolute positions describe this source design, not every Transformer.'])
FHEAD=formula('U=Eᵀ; u=hU; y_j=exp(u_j)/Σ_r exp(u_r)',{'E':'|Vocab|×d input embedding matrix','U':'d×|Vocab| tied output projection','h':'1×d final contextual row at the last available prefix position','u':'1×|Vocab| vocabulary logits','y':'1×|Vocab| vocabulary probability vector','j,r':'vocabulary-entry indices','|Vocab|':'vocabulary size','d':'model feature width'},{'E,U,h,u':'dimensionless weights/activations/logits','y':'dimensionless probabilities','j,r,|Vocab|,d':'dimensionless indices/counts'},['Tied weights as explicitly shown; no output bias or temperature modification in this model; softmax is over vocabulary entries.'])
